// Decode once per mounted piece. Each delta is a two-byte cell index and tone.
export default function foxGirl(): Frame {
  const frames: Uint8Array[] = [];
  const unpack = (data: string) => Uint8Array.from(atob(data), (ch) => ch.charCodeAt(0));
  const first = unpack(DATA[0]);
  const pixels = new Uint8Array(meta.cols * meta.rows);
  for (let i = 0; i < first.length; i++) {
    pixels[i * 2] = first[i] >> 4;
    pixels[i * 2 + 1] = first[i] & 15;
  }
  frames.push(pixels);
  for (let f = 1; f < DATA.length; f++) {
    const next = frames[f - 1].slice();
    const change = unpack(DATA[f]);
    for (let i = 0; i < change.length; i += 2) {
      const value = (change[i] << 8) | change[i + 1];
      next[value >> 3] = value & 7;
    }
    frames.push(next);
  }
  const asText = (frame: Uint8Array) => {
    const lines: string[] = [];
    for (let y = 0; y < meta.rows; y++) {
      let line = "";
      for (let x = 0; x < meta.cols; x++) {
        const tone = frame[y * meta.cols + x];
        line += RAMP[tone];
      }
      lines.push(line);
    }
    return lines.join("\n");
  };
  const art = frames.map(asText);

  return (t, { color } = {}) => {
    const i = ((Math.floor(t * meta.fps) % frames.length) + frames.length) % frames.length;
    if (color) color.set(frames[i]);
    return art[i];
  };
}
